import datetime, os, socket, ssl, tempfile, threading
from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec, ed25519, rsa
from cryptography.x509.oid import NameOID

# ---- lab: small TLS servers on 127.0.0.1 that this script starts and then discovers. Certificates are self-signed and generated now. ----
def make_cert(kind, cn, valid_from_days, valid_to_days):
    if kind == "rsa1024": key = rsa.generate_private_key(65537, 1024)
    elif kind == "rsa2048": key = rsa.generate_private_key(65537, 2048)
    elif kind == "ec256": key = ec.generate_private_key(ec.SECP256R1())
    elif kind == "ed25519": key = ed25519.Ed25519PrivateKey.generate()
    sign_hash = None if kind == "ed25519" else hashes.SHA256()
    name = x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, cn)])
    now = datetime.datetime.now(datetime.timezone.utc)
    cert = (x509.CertificateBuilder().subject_name(name).issuer_name(name).public_key(key.public_key()).serial_number(x509.random_serial_number())
            .not_valid_before(now + datetime.timedelta(days=valid_from_days)).not_valid_after(now + datetime.timedelta(days=valid_to_days))
            .add_extension(x509.SubjectAlternativeName([x509.DNSName(cn)]), critical=False).sign(key, sign_hash))
    return key, cert

LAB = [  # label, key kind, common name, validity (from, to) in days relative to now, highest TLS version the server accepts
    ("web-front",      "rsa2048", "web.lab.test",     (-30, 335), ssl.TLSVersion.TLSv1_3),
    ("legacy-billing", "rsa1024", "billing.lab.test", (-900, 200), ssl.TLSVersion.TLSv1_2),
    ("api-gateway",    "ec256",   "api.lab.test",     (-10, 80),  ssl.TLSVersion.TLSv1_3),
    ("old-intranet",   "rsa2048", "intra.lab.test",   (-400, -35), ssl.TLSVersion.TLSv1_2),
    ("edge-device",    "ed25519", "edge.lab.test",    (-5, 3000), ssl.TLSVersion.TLSv1_3),
]
_tmp = tempfile.mkdtemp()
_next_port = [47100]
def bind_free():
    """bind the next free port from 47100 upwards on 127.0.0.1 (a fixed small range makes the discovery sweep below short and repeatable)"""
    while True:
        s = socket.socket()
        try:
            s.bind(("127.0.0.1", _next_port[0])); s.listen(16); _next_port[0] += 1
            return s
        except OSError:
            s.close(); _next_port[0] += 1
def start_lab():
    servers = {}
    for label, kind, cn, (a, b), maxv in LAB:
        key, cert = make_cert(kind, cn, a, b)
        cf, kf = os.path.join(_tmp, label + ".crt"), os.path.join(_tmp, label + ".key")
        open(cf, "wb").write(cert.public_bytes(serialization.Encoding.PEM))
        open(kf, "wb").write(key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
        ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        ctx.minimum_version = ssl.TLSVersion.TLSv1_2
        ctx.maximum_version = maxv
        ctx.set_ciphers("DEFAULT:@SECLEVEL=0")
        ctx.load_cert_chain(cf, kf)
        sock = bind_free()
        def serve(s=sock, c=ctx):
            while True:
                try:
                    conn, _ = s.accept()
                except OSError:
                    return
                try:
                    with c.wrap_socket(conn, server_side=True) as t:
                        t.settimeout(1)
                except Exception:
                    pass
        threading.Thread(target=serve, daemon=True).start()
        servers[label] = sock.getsockname()[1]
    return servers

def probe(port, minv=None, maxv=None):
    """TLS client handshake to 127.0.0.1:port; returns (version, cipher, DER certificate) or None if the server refuses"""
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE
    ctx.set_ciphers("DEFAULT:@SECLEVEL=0")
    ctx.minimum_version = minv or ssl.TLSVersion.MINIMUM_SUPPORTED
    if maxv: ctx.maximum_version = maxv
    try:
        with socket.create_connection(("127.0.0.1", port), timeout=3) as raw:
            with ctx.wrap_socket(raw) as t:
                return t.version(), t.cipher()[0], t.getpeercert(binary_form=True)
    except (ssl.SSLError, OSError):
        return None

def describe_key(cert):
    pk = cert.public_key()
    if isinstance(pk, rsa.RSAPublicKey): return "RSA", pk.key_size
    if isinstance(pk, ec.EllipticCurvePublicKey): return "EC " + pk.curve.name, pk.key_size
    if isinstance(pk, ed25519.Ed25519PublicKey): return "Ed25519", 256
    return type(pk).__name__, 0

def start_plain(payload):
    """a non-TLS service that sends 'payload' bytes to every client and closes (used for banner and SSH-style discovery)"""
    sock = bind_free()
    def serve():
        while True:
            try:
                conn, _ = sock.accept()
            except OSError:
                return
            try:
                conn.sendall(payload)
            except OSError:
                pass
            conn.close()
    threading.Thread(target=serve, daemon=True).start()
    return sock.getsockname()[1]
# Certificate discovery: collect every certificate the lab presents and record the fields an inventory needs.
ports = start_lab()
now = datetime.datetime.now(datetime.timezone.utc)
def expiry_bucket(cert):
    left = (cert.not_valid_after_utc - now).days
    return "EXPIRED" if left < 0 else "within 90 days" if left <= 90 else "valid (> 90 days)"
rows = []
for label, port in ports.items():
    version, cipher, der = probe(port)
    c = x509.load_der_x509_certificate(der)
    alg, size = describe_key(c)
    sans = [n.value for n in c.extensions.get_extension_for_class(x509.SubjectAlternativeName).value]
    sig = c.signature_algorithm_oid._name
    life = (c.not_valid_after_utc - c.not_valid_before_utc).days
    issues = []
    if alg == "RSA" and size < 2048: issues.append(f"RSA key of only {size} bits")
    if expiry_bucket(c) == "EXPIRED": issues.append("expired")
    elif expiry_bucket(c) == "within 90 days": issues.append("expires within 90 days")
    if c.issuer == c.subject: issues.append("self-signed (lab certificates; a production host would show a CA chain)")
    if life > 398: issues.append(f"validity of {life // 30} months exceeds the 398-day public TLS limit (not applicable to private CAs)")
    rows.append((label, c.subject.rfc4514_string(), sans, f"{alg} {size}", sig, expiry_bucket(c), life, issues))
print(f"{'service':<16} {'subject':<22} {'key':<18} {'signature':<24} {'validity status':<18} {'lifetime (days)':>15}")
for label, subj, sans, key, sig, status, life, _ in rows:
    print(f"{label:<16} {subj:<22} {key:<18} {sig:<24} {status:<18} {life:>15}")
print()
print("findings from the certificate inventory:")
for label, *_, issues in rows:
    for i in issues:
        print(f"  {label:<16} {i}")
print()
print("quantum relevance: every key above (RSA, EC, Ed25519) would have to be replaced by a post-quantum or hybrid certificate for authentication to survive a CRQC; the inventory shows which certificates exist, who issues them and when they expire, which is the order in which replacement can be scheduled at no extra cost (replace at renewal)")

import ast, os, re, tempfile, textwrap
# Application discovery by static analysis of source code. The scanned tree is a small SAMPLE written by this script (DEMO DATA), not a real code base.
root = tempfile.mkdtemp()
files = {
 "billing/pay.py": '''
import hashlib, hmac, jwt
from cryptography.hazmat.primitives.asymmetric import rsa
KEY = rsa.generate_private_key(public_exponent=65537, key_size=2048)
def fingerprint(card): return hashlib.md5(card.encode()).hexdigest()
def sign_token(claims, secret): return jwt.encode(claims, secret, algorithm="HS256")
def sign_api(claims, key): return jwt.encode(claims, key, algorithm="RS256")
def tag(msg, k): return hmac.new(k, msg, hashlib.sha256).hexdigest()
''',
 "billing/legacy.py": '''
import hashlib
from cryptography.hazmat.primitives.asymmetric import rsa
def old_hash(data): return hashlib.sha1(data).hexdigest()
OLD_KEY = rsa.generate_private_key(65537, 1024)
''',
 "billing/dynamic.py": '''
import hashlib
from config import SETTINGS
def digest(data):
    return hashlib.new(SETTINGS["hash_algorithm"], data).hexdigest()   # algorithm chosen at run time
''',
 "web/Auth.java": '''
import java.security.*;
class Auth {
  MessageDigest md = MessageDigest.getInstance("SHA-1");
  KeyPairGenerator g = KeyPairGenerator.getInstance("RSA");
  Cipher c = Cipher.getInstance("RSA/ECB/PKCS1Padding");
  Cipher d = Cipher.getInstance("AES/GCM/NoPadding");
}
''',
 "web/server.js": '''
const crypto = require('crypto');
const h = crypto.createHash('sha1');
const k = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
''',
 "deploy/nginx.conf": '''
ssl_protocols TLSv1 TLSv1.1 TLSv1.2;
ssl_ciphers HIGH:!aNULL:!MD5;
ssl_ecdh_curve prime256v1;
''',
}
for rel, text in files.items():
    path = os.path.join(root, rel); os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path, "w", encoding="utf-8").write(textwrap.dedent(text))
findings = []
def add(rel, line, cls, what):
    findings.append((rel, line, cls, what))
for rel in files:
    text = open(os.path.join(root, rel), encoding="utf-8").read()
    if rel.endswith(".py"):
        tree = ast.parse(text)
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                f = ast.unparse(node.func)
                if f in ("hashlib.md5", "hashlib.sha1"):
                    add(rel, node.lineno, "weak hash (classically broken or deprecated)", f)
                if f.endswith("generate_private_key"):
                    size = next((k.value.value for k in node.keywords if k.arg == "key_size"), node.args[1].value if len(node.args) > 1 else None)
                    add(rel, node.lineno, "quantum-vulnerable public key" + (" and short key" if size and size < 2048 else ""), f"RSA {size} bits")
                if f == "jwt.encode":
                    alg = next((k.value.value for k in node.keywords if k.arg == "algorithm"), "?")
                    add(rel, node.lineno, "JWT algorithm" + (" (RSA: quantum-vulnerable)" if alg.startswith("RS") else " (HMAC: not affected by Shor)"), alg)
                if f == "hashlib.new" and not isinstance(node.args[0], ast.Constant):
                    add(rel, node.lineno, "algorithm chosen at run time: CANNOT be determined statically", "hashlib.new(<variable>)")
    else:
        rules = [(r'getInstance\("(MD5|SHA-1)"\)', "weak hash"), (r'getInstance\("RSA"\)', "quantum-vulnerable public key"),
                 (r'"RSA/ECB/PKCS1Padding"', "RSA with PKCS#1 v1.5 encryption padding"), (r"createHash\('(md5|sha1)'\)", "weak hash"),
                 (r"generateKeyPairSync\('ec'", "quantum-vulnerable public key (elliptic curve)"), (r"ssl_protocols .*TLSv1 ", "legacy TLS 1.0/1.1 enabled"),
                 (r"ssl_ecdh_curve", "quantum-vulnerable key-exchange group (no PQC group configured)")]
        for n, line in enumerate(text.splitlines(), 1):
            for rx, cls in rules:
                m = re.search(rx, line)
                if m: add(rel, n, cls, m.group(0))
findings.sort(key=lambda f: (f[0], f[1]))
print(f"{'file':<20} {'line':>4}  {'class':<62} evidence")
for rel, ln, cls, what in findings:
    print(f"{rel:<20} {ln:>4}  {cls:<62} {what}")
print()
by = {}
for _, _, cls, _ in findings:
    key = "quantum-vulnerable" if "quantum-vulnerable" in cls else "weak / legacy" if ("weak" in cls or "legacy" in cls or "PKCS#1" in cls) else "other"
    by[key] = by.get(key, 0) + 1
print("summary:", by, "| not determinable statically:", sum(1 for f in findings if "CANNOT" in f[2]))
print("limits: static analysis finds literal algorithm names only. 'hashlib.new(SETTINGS[...])' is reported as undeterminable, wrapper functions, reflection and values from configuration or the environment are invisible, and a match is a candidate, not proof that the code path runs; results are combined with runtime discovery (2.3) and the dependency map (2.7)")
